package app.rokh.fitness;
import android.app.Activity; import android.os.Bundle; import android.webkit.*;
public class MainActivity extends Activity { WebView web; public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDefaultTextEncodingName("UTF-8");web.setWebViewClient(new WebViewClient());web.loadUrl("file:///android_asset/index.html");} public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}}